    # Your HTTP Login Endpoint (for getting token/session)
    LOGIN_URL = "https://staging.phone-diagnostics.com/v1/login"  # CHANGE THIS
    
    # Your WebSocket Endpoint
    WS_URL = "wss://staging.phone-diagnostics.com/v1/ws"  # CHANGE THIS
    
    # Your Test Credentials
    USERNAME = "anas-qa"  # CHANGE THIS
    PASSWORD = "Qd8n5v6i"  # CHANGE THIS
    
