    def on_start(self):
        """Called when a user starts - handles login and WebSocket connection"""
        logger.info(f"🟢 User starting... Attempting login for: {self.USERNAME}")
        
        try:
            # Step 1: Login via HTTP to get token
            login_data = {
                "username": self.USERNAME,
                "password": self.PASSWORD
            }
            
            logger.info(f"📡 Sending login request to: {self.LOGIN_URL}")
            
            start_time = time.time()
            response = requests.post(self.LOGIN_URL, json=login_data, timeout=10)
            response_time = int((time.time() - start_time) * 1000)
            
            logger.info(f"📡 Login response status: {response.status_code}")
            
            if response.status_code == 200:
                # Parse the response
                try:
                    response_data = response.json()
                    logger.info(f"📦 Response data: {json.dumps(response_data, indent=2)}")
                    
                    # 👇 UPDATE THIS LINE BASED ON YOUR API RESPONSE STRUCTURE
                    token = (
                        response_data.get("access_token") or 
                        response_data.get("token") or 
                        response_data.get("data", {}).get("token") or
                        response_data.get("data", {}).get("access_token")
                    )
                    
                    if token:
                        self.token = token
                        logger.info(f"✅ Login successful! Token obtained: {token[:30]}...")
                        
                        # Step 2: Connect WebSocket with Bearer Token in Headers
                        logger.info(f"🔌 Connecting WebSocket to: {self.WS_URL}")
                        
                        headers = {
                            "Authorization": f"Bearer {token}"
                        }
                        
                        self.ws = websocket.create_connection(
                            self.WS_URL,
                            header=headers,
                            timeout=10
                        )
                        
                        # ✅ LOG CONNECTION SUCCESS
                        logger.info("=" * 60)
                        logger.info("✅✅✅ WEBSOCKET CONNECTION SUCCESSFUL! ✅✅✅")
                        logger.info(f"🔗 Connected to: {self.WS_URL}")
                        logger.info(f"🔑 Using token: {token[:30]}...")
                        logger.info(f"👤 User: {self.USERNAME}")
                        logger.info("=" * 60)
                        
                        # ✅ Send a test message to verify connection
                        self._send_websocket_message({
                            "type": "ping",
                            "message": "Connection test from Locust",
                            "timestamp": int(time.time())
                        })
                        
                    else:
                        logger.error(f"❌ No token found in response: {response_data}")
                        logger.error(f"📄 Response keys: {list(response_data.keys())}")
                        self.stop()
                        
                except json.JSONDecodeError:
                    logger.error(f"❌ Response is not valid JSON: {response.text[:200]}")
                    self.stop()
                    
            else:
                logger.error(f"❌ Login failed with status {response.status_code}")
                logger.error(f"📄 Response: {response.text[:200]}")
                self.stop()
                
        except requests.exceptions.ConnectionError:
            logger.error(f"❌ Could not connect to {self.LOGIN_URL}. Is the server running?")
            self.stop()
        except requests.exceptions.Timeout:
            logger.error(f"❌ Login request timed out after 10 seconds")
            self.stop()
        except websocket.WebSocketConnectionClosedException:
            logger.error(f"❌ WebSocket connection closed unexpectedly")
            self.stop()
        except websocket.WebSocketBadStatusException as e:
            logger.error(f"❌ WebSocket connection failed with status: {e}")
            logger.error(f"🔍 Check if your WebSocket URL is correct and accepts Bearer tokens")
            self.stop()
        except Exception as e:
            logger.error(f"❌ Unexpected error: {str(e)}")
            import traceback
            logger.error(traceback.format_exc())
            self.stop()

    # ============================================================
    # 📤 FUNCTION TO SEND WEBSOCKET MESSAGES
    # ============================================================
    def _send_websocket_message(self, message_data):
        """
        Send a message to the WebSocket and print the response.
        
        Args:
            message_data: Dictionary containing the message to send
        
        Returns:
            The response from the WebSocket or None if failed
        """
        if not hasattr(self, 'ws') or self.ws is None:
            logger.error("❌ WebSocket not connected. Cannot send message.")
            return None
        
        try:
            # Convert message to JSON string
            message = json.dumps(message_data)
            
            # Send the message
            logger.info(f"📤 Sending message: {json.dumps(message_data, indent=2)}")
            self.ws.send(message)
            
            # Receive response (with timeout)
            self.ws.settimeout(5)
            response = self.ws.recv()
            
            # Parse response if it's JSON
            try:
                response_data = json.loads(response)
                logger.info(f"📥 Received response: {json.dumps(response_data, indent=2)}")
                return response_data
            except json.JSONDecodeError:
                logger.info(f"📥 Received response (raw): {response}")
                return response
                
        except websocket.WebSocketTimeoutException:
            logger.error("⏰ WebSocket receive timeout")
            return None
        except websocket.WebSocketConnectionClosedException:
            logger.error("🔌 WebSocket connection closed")
            return None
        except Exception as e:
            logger.error(f"❌ Error sending message: {str(e)}")
            return None
    # ============================================================

