    def send_message(self, custom_message=None):
        """
        Send a message to the WebSocket.
        
        👇 ADD YOUR MESSAGES HERE
        """
        # ============================================================
        # 🔥 ADD YOUR MESSAGES HERE - CUSTOMIZE THIS BLOCK
        # ============================================================
        
        # Example 1: Simple ping message
        message = {
            "type": "ping",
            "timestamp": int(time.time())
        }
        
        # Example 2: Chat message (uncomment to use)
        # message = {
        #     "type": "chat",
        #     "room": "general",
        #     "content": "Hello from Locust!",
        #     "user": self.USERNAME,
        #     "timestamp": int(time.time())
        # }
        
        # Example 3: Custom message from parameter
        if custom_message:
            message = custom_message
        
        # Example 4: Authentication check
        # message = {
        #     "type": "auth_check",
        #     "token": self.token
        # }
        
        # Example 5: Join a room
        # message = {
        #     "type": "join_room",
        #     "room": "test_room"
        # }
        
        # ============================================================
        # 🔥 END OF YOUR CUSTOM MESSAGE SECTION
        # ============================================================
        
        # Send the message and log response
        start_time = time.time()
        response = self._send_websocket_message(message)
        total_time = int((time.time() - start_time) * 1000)
        
        # Report to Locust statistics
        if response is not None:
            self.environment.events.request.fire(
                request_type="WS",
                name=message.get("type", "message"),
                response_time=total_time,
                response_length=len(str(response)),
                context={"user": self.USERNAME}
            )
            logger.info(f"✅ Message round-trip: {total_time}ms")
            logger.info(f"📊 Response data: {response}")
        else:
            self.environment.events.request.fire(
                request_type="WS",
                name=message.get("type", "message"),
                response_time=total_time,
                response_length=0,
                exception=Exception("No response received")
            )
            logger.error(f"❌ No response received for message")
        
        return response
