    def on_stop(self):
        """Called when a user stops"""
        logger.info(f"🔴 User stopping for: {self.USERNAME}")
        try:
            if hasattr(self, 'ws') and self.ws:
                self.ws.close()
                logger.info("✅ WebSocket closed")
        except Exception as e:
            logger.error(f"❌ Error closing WebSocket: {str(e)}")